SELECT cr.cr_returned_date_sk, cr.cr_return_quantity, cr.cr_return_amount, ca.ca_state, (cr.cr_return_amount * 1.1) AS return_amount_with_tax, CASE WHEN cr.cr_return_quantity > 61 THEN 'HIGH' WHEN cr.cr_return_quantity = 1 THEN 'MEDIUM' ELSE 'LOW' END AS quantity_category, CASE WHEN ca.ca_gmt_offset >= -6.00 THEN 'EAST' ELSE 'WEST' END AS region, cr.cr_return_amount - cr.cr_return_tax AS net_return_amount, cr.cr_return_amount + cr.cr_fee + cr.cr_return_ship_cost AS total_cost, CONCAT(ca.ca_city, ', ', ca.ca_state) AS city_state FROM catalog_returns cr JOIN customer_address ca ON cr.cr_refunded_addr_sk = ca.ca_address_sk WHERE cr.cr_returned_date_sk = 2451034 AND ca.ca_country = 'United States'
